INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch08$PT143-S4-Q12$batch08$, 143, 4, 12, $batch08$Paradox$batch08$, $batch08$After the rush-hour speed limit on the British M25 motorway was lowered from 70 miles per hour (115 kilometers per hour) to 50 miles per hour (80 kilometers per hour), rush-hour travel times decreased by approximately 15 percent.$batch08$, $batch08$Which one of the following, if true, most helps to explain the decrease in travel times described above?$batch08$, $batch08$C$batch08$, true, $batch08$Batch 08; question text from local bank.$batch08$ FROM lr_sections s WHERE s.preptest=143 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch08$PT143-S4-Q12$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$A$batch08$, $batch08$After the decrease in the rush-hour speed limit, the average speed on the M25 was significantly lower during rush hours than at other times of the day.$batch08$, $batch08$Deepens Paradox$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT143-S4-Q12$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$A$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$B$batch08$, $batch08$Travel times during periods other than rush hours were essentially unchanged after the rush-hour speed limit was lowered.$batch08$, $batch08$Out of Scope$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT143-S4-Q12$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$B$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$C$batch08$, $batch08$Before the rush-hour speed limit was lowered, rush-hour accidents that caused lengthy delays were common, and most of these accidents were caused by high-speed driving.$batch08$, $batch08$Correct$batch08$, true FROM lr_questions q WHERE q.qid=$batch08$PT143-S4-Q12$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$C$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$D$batch08$, $batch08$Enforcement of speed limits on the M25 was quite rigorous both before and after the rush-hour speed limit was lowered.$batch08$, $batch08$Deepens Paradox$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT143-S4-Q12$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$D$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$E$batch08$, $batch08$The number of people who drive on the M25 during rush hours did not increase after the rush-hour speed limit was lowered.$batch08$, $batch08$Weaker Impact$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT143-S4-Q12$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$E$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch08$PT143-S4-Q12$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch08$Given that$batch08$, $batch08$The rush-hour speed limit on the M25 dropped from 70 mph to 50 mph.$batch08$), (1, $batch08$How can it be that$batch08$, $batch08$Rush-hour travel times fell by about 15%?$batch08$), (2, $batch08$Evaluate$batch08$, $batch08$Slower driving should mean longer trips. So something other than raw speed must have been costing time before. Think about what high speed causes in heavy traffic: accidents, and accidents cause long delays.$batch08$), (3, $batch08$Goal$batch08$, $batch08$A source of delay that the higher speed limit was causing.$batch08$)) v(position,label,body) WHERE q.qid=$batch08$PT143-S4-Q12$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch08$A$batch08$, $batch08$Lower average speeds make faster trips even more puzzling.$batch08$), ($batch08$B$batch08$, $batch08$Other times of day don't explain why rush hour got faster.$batch08$), ($batch08$C$batch08$, $batch08$High-speed driving caused accidents and long delays. Slow the traffic and the delays go away, which more than makes up for the lower speed.$batch08$), ($batch08$D$batch08$, $batch08$If the limits were strictly enforced, drivers really did go slower. That makes the faster trips harder to explain.$batch08$), ($batch08$E$batch08$, $batch08$Traffic not *increasing* rules out one reason trips might get slower. It gives no reason they got faster.$batch08$)) v(letter,body) WHERE q.qid=$batch08$PT143-S4-Q12$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
